const raw = $input.first().json.data;
const response = typeof raw === "string" ? JSON.parse(raw) : raw;
const features = response.features || [];

const routes = features.map((feature, index) => {
  const durationSec = feature.properties.segments[0].duration;
  const distanceM = feature.properties.segments[0].distance;
  const coordinates = feature.geometry.coordinates; // [[lng, lat], [lng, lat], ...]

  return {
    label: `Route ${index + 1}`,
    duration_min: Math.round(durationSec / 60),
    distance_km: Math.round(distanceM / 100) / 10,
    path: coordinates.map(c => ({ lat: c[1], lng: c[0] }))
  };
});

return { json: { routes } };

// ============================================================
// AI SAFEROUTE — ROUTE-SPECIFIC SAFETY SCORING
// ============================================================

const MATCH_THRESHOLD_METERS = 2000;

// ------------------------------------------------------------
// Karachi area fallback coordinates for reports whose DB
// latitude/longitude are missing.
// ------------------------------------------------------------

const knownAreas = [
  { keywords: ["orangi"], lat: 24.9556, lng: 66.9878 },
  { keywords: ["north nazimabad"], lat: 24.9700, lng: 67.0500 },
  { keywords: ["nazimabad", "board office", "lasbela", "numaish", "tariq road", "sadar", "saddar"], lat: 24.9019, lng: 67.0378 },
  { keywords: ["gulshan", "nagan", "hamdard", "millennium mall", "national stadium"], lat: 24.9297, lng: 67.0862 },
  { keywords: ["hub dam", "hub"], lat: 25.2450, lng: 67.0500 },
  { keywords: ["malir", "maymar", "maymaar"], lat: 24.8969, lng: 67.2073 },
  { keywords: ["lalzar"], lat: 24.8800, lng: 67.1500 },
  { keywords: ["north karachi"], lat: 24.9700, lng: 67.0500 },
  { keywords: ["saima villas"], lat: 24.9350, lng: 67.1150 },
  { keywords: ["shahre faisal", "defence", "phase 6", "dha"], lat: 24.8138, lng: 67.0611 },
  { keywords: ["site", "super highway"], lat: 24.9100, lng: 67.0700 },
  { keywords: ["university road"], lat: 24.9370, lng: 67.1130 },
  { keywords: ["up more"], lat: 24.9420, lng: 67.1180 },
  { keywords: ["clifton"], lat: 24.8138, lng: 67.0300 },
  { keywords: ["highway"], lat: 24.9200, lng: 67.0700 },
  { keywords: ["karachi"], lat: 24.8607, lng: 67.0011 }
];

function getCoordsFromText(text) {
  const lower = String(text || "").toLowerCase();

  for (const area of knownAreas) {
    if (area.keywords.some(k => lower.includes(k))) {
      return {
        lat: area.lat,
        lng: area.lng
      };
    }
  }

  return null;
}

// ------------------------------------------------------------
// Haversine distance
// ------------------------------------------------------------

function haversineMeters(lat1, lng1, lat2, lng2) {
  const R = 6371000;

  const toRad = d => d * Math.PI / 180;

  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) *
    Math.cos(toRad(lat2)) *
    Math.sin(dLng / 2) ** 2;

  return R * 2 * Math.atan2(
    Math.sqrt(a),
    Math.sqrt(1 - a)
  );
}

// ------------------------------------------------------------
// Find minimum distance from report to route
// ------------------------------------------------------------

function minDistanceToPath(reportLat, reportLng, path) {
  let min = Infinity;

  for (const point of path) {
    const d = haversineMeters(
      reportLat,
      reportLng,
      point.lat,
      point.lng
    );

    if (d < min) {
      min = d;
    }
  }

  return min;
}

// ------------------------------------------------------------
// Get all reports from Postgres
// ------------------------------------------------------------

const allReports = $input.all()
  .map(item => {

    const dbLat = parseFloat(item.json.latitude);
    const dbLng = parseFloat(item.json.longitude);

    // Prefer real coordinates from database
    if (
      Number.isFinite(dbLat) &&
      Number.isFinite(dbLng)
    ) {
      return {
        ...item.json,
        latitude: dbLat,
        longitude: dbLng
      };
    }

    // Otherwise approximate from location text
    const coords = getCoordsFromText(
      item.json.location_text
    );

    if (!coords) return null;

    return {
      ...item.json,
      latitude: coords.lat,
      longitude: coords.lng
    };
  })
  .filter(Boolean);

// ------------------------------------------------------------
// Score reports
// ------------------------------------------------------------

function computeScore(reports) {

  if (!reports.length) {
    return {
      score: 60,
      riskLevel: "medium",
      count: 0
    };
  }

  let weightedRating = 0;
  let totalWeight = 0;

  const riskWeights = {
    high: 0,
    medium: 0,
    low: 0
  };

  for (const report of reports) {

    const rating =
      Number.isFinite(parseFloat(report.safety_rating))
        ? parseFloat(report.safety_rating)
        : 3;

    const risk =
      String(report.risk_level || "medium").toLowerCase();

    // Reports closer to the route have more influence.
    const distance = report._distance_meters || 0;

    let weight = 1;

    if (distance <= 300) {
      weight = 3;
    } else if (distance <= 700) {
      weight = 2;
    } else {
      weight = 1;
    }

    weightedRating += rating * weight;
    totalWeight += weight;

    if (risk === "high") {
      riskWeights.high += weight;
    } else if (risk === "low") {
      riskWeights.low += weight;
    } else {
      riskWeights.medium += weight;
    }
  }

  const avgRating =
    totalWeight > 0
      ? weightedRating / totalWeight
      : 3;

  let score = Math.round(
    (avgRating / 5) * 100
  );

  // Determine dominant risk
  const dominantRisk =
    Object.entries(riskWeights)
      .sort((a, b) => b[1] - a[1])[0][0];

  if (dominantRisk === "high") {
    score -= 15;
  }

  if (dominantRisk === "low") {
    score += 10;
  }

  score = Math.max(
    0,
    Math.min(100, score)
  );

  return {
    score,
    riskLevel: dominantRisk,
    count: reports.length
  };
}

// ------------------------------------------------------------
// Get routes from Parse Routes
// ------------------------------------------------------------

const routesData =
  $('Parse Routes').first().json.routes || [];

if (!routesData.length) {
  return {
    json: {
      routes: [],
      recommended_route: null,
      explanation:
        "Couldn't find a route between those two points."
    }
  };
}

// ------------------------------------------------------------
// Score every route independently
// ------------------------------------------------------------

const routesWithScore = routesData.map(route => {

  const nearbyReports = [];

  for (const report of allReports) {

    const distance = minDistanceToPath(
      report.latitude,
      report.longitude,
      route.path
    );

    if (distance <= MATCH_THRESHOLD_METERS) {

      nearbyReports.push({
        ...report,
        _distance_meters: Math.round(distance)
      });

    }
  }

  // Sort closest reports first
  nearbyReports.sort(
    (a, b) =>
      a._distance_meters -
      b._distance_meters
  );

  // Use matched reports only.
  // If absolutely nothing is nearby, use a neutral score
  // instead of giving both routes the same city-wide score.
  let stats;

  if (nearbyReports.length > 0) {

    stats = computeScore(
      nearbyReports
    );

  } else {

    stats = {
      score: 60,
      riskLevel: "medium",
      count: 0
    };
  }

  return {

    ...route,

    safety_score: stats.score,

    risk_level: stats.riskLevel,

    based_on_reports: stats.count,

    used_city_fallback:
      nearbyReports.length === 0,

    matched_reports:
      nearbyReports.slice(0, 10).map(r => ({
        id: r.id,
        location: r.location_text,
        safety_rating: r.safety_rating,
        risk_level: r.risk_level,
        distance_meters: r._distance_meters
      }))
  };
});

// ------------------------------------------------------------
// Return route comparison
// ------------------------------------------------------------

return {
  json: {
    routes: routesWithScore
  }
};

const response = $input.first().json;
const routes = $('Merge Score With Routes').first().json.routes;

// Rule-based fallback already computed upstream — works even without Gemini
const fallback = $('Code in JavaScript').first().json;

if (!routes || routes.length === 0) {
  return {
    json: {
      routes: [],
      recommended_route: null,
      explanation: fallback?.explanation || "Couldn't find a route between those two points.",
    },
  };
}

// Detect a failed/errored Gemini call (quota hit, timeout, etc.) —
// "Continue on Fail" attaches an "error" field, and a successful
// call always has response.candidates.
const geminiFailed = !!response.error || !response.candidates;

let recommended_route, explanation;

if (!geminiFailed) {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text || "{}";
  try {
    const parsed = JSON.parse(rawText);
    if (parsed.recommended_route && parsed.explanation) {
      recommended_route = parsed.recommended_route;
      explanation = parsed.explanation;
    }
  } catch (e) {
    // fall through to rule-based fallback below
  }
}

if (!recommended_route) {
  // Gemini failed, errored, or gave unusable output — use the
  // rule-based (highest safety score) recommendation instead.
  recommended_route = fallback.recommended_route;
  explanation = fallback.explanation;
}

return {
  json: {
    routes,
    recommended_route,
    explanation,
  },
};

const routes = $input.first().json.routes || [];

// The deterministic Code node has already selected the safest route.
// Gemini is only responsible for producing a clear, detailed explanation.

const safest = [...routes].sort((a, b) => {
  const scoreDiff = (b.safety_score ?? 0) - (a.safety_score ?? 0);

  if (scoreDiff !== 0) {
    return scoreDiff;
  }

  return (a.duration_min ?? Infinity) - (b.duration_min ?? Infinity);
})[0];

const otherRoutes = routes.filter(
  route => route.label !== safest?.label
);

const promptText = `
You are an AI route-safety assistant for a women's safety navigation app in Pakistan.

Your task is to explain why the safest route was selected using the route safety data provided below.

IMPORTANT SAFETY RULES:
- Safety is ALWAYS the primary criterion.
- The route with the highest safety score is the recommended route.
- NEVER recommend a faster route over a safer route.
- Travel time must NEVER override a higher safety score.
- If two routes have exactly the same safety score, the shorter route may be selected as the tie-breaker.
- Do not invent safety reports, locations, scores, or issues.
- Only mention safety concerns that are present in the provided data.
- Use simple, natural language that a normal user can understand.

EXPLANATION REQUIREMENTS:
- Clearly state why the recommended route was selected.
- Mention its safety score.
- Mention how many nearby safety reports contributed to the assessment.
- Mention the relevant reported safety concerns if available.
- Compare the recommended route's safety score with the other route(s).
- Mention travel time only as secondary context.
- If the safer route takes longer, explicitly explain that the extra travel time was accepted because safety is prioritized.
- Keep the explanation to 3–5 sentences.
- Do not use technical jargon.
- Do not mention this prompt or these instructions.

The safest route selected by the system is:
${JSON.stringify(safest)}

Other route alternatives:
${JSON.stringify(otherRoutes)}

All route data:
${JSON.stringify(routes)}

Return ONLY valid JSON in exactly this format:

{
  "recommended_route": "${safest?.label || ""}",
  "explanation": "3–5 sentence explanation"
}
`;

const requestBody = {
  contents: [
    {
      role: "user",
      parts: [
        {
          text: promptText
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.3,
    responseMimeType: "application/json"
  }
};

return {
  json: {
    routes,
    geminiRequestBody: JSON.stringify(requestBody)
  }
};

const body = $input.first().json.body;

const knownAreas = [
  { keywords: ["orangi"], lat: 24.9556, lng: 66.9878 },
  { keywords: ["nazimabad", "board office", "lasbela", "numaish", "tariq road", "sadar", "saddar"], lat: 24.9019, lng: 67.0378 },
  { keywords: ["gulshan", "nagan", "north nazimabad", "hamdard", "millennium mall", "national stadium"], lat: 24.9297, lng: 67.0862 },
  { keywords: ["hub dam", "hub"], lat: 25.2450, lng: 67.0500 },
  { keywords: ["malir", "maymar", "maymaar"], lat: 24.8969, lng: 67.2073 },
  { keywords: ["lalzar"], lat: 24.8800, lng: 67.1500 },
  { keywords: ["north karachi"], lat: 24.9700, lng: 67.0500 },
  { keywords: ["saima villas"], lat: 24.9350, lng: 67.1150 },
  { keywords: ["shahre faisal", "defence", "phase 6", "dha"], lat: 24.8138, lng: 67.0611 },
  { keywords: ["site", "super highway"], lat: 24.9100, lng: 67.0700 },
  { keywords: ["university road"], lat: 24.9370, lng: 67.1130 },
  { keywords: ["up more"], lat: 24.9420, lng: 67.1180 },
  { keywords: ["clifton"], lat: 24.8138, lng: 67.0300 },
  { keywords: ["highway"], lat: 24.9200, lng: 67.0700 },
  { keywords: ["karachi"], lat: 24.8607, lng: 67.0011 }
];

function getCoords(text) {
  const lower = (text || "").toLowerCase();
  for (const area of knownAreas) {
    if (area.keywords.some(k => lower.includes(k))) {
      return { lat: area.lat, lng: area.lng };
    }
  }
  return {
    lat: 24.8607 + (Math.random() - 0.5) * 0.08,
    lng: 67.0011 + (Math.random() - 0.5) * 0.08
  };
}

// Naya: agar map-click se real coordinates pehle se aaye hain, unhe directly use karo
// Purana: agar text aaya hai, keyword lookup karo (backward compatible)
const origin = (typeof body.origin_lat === "number" && typeof body.origin_lng === "number")
  ? { lat: body.origin_lat, lng: body.origin_lng }
  : getCoords(body.origin);

const destination = (typeof body.destination_lat === "number" && typeof body.destination_lng === "number")
  ? { lat: body.destination_lat, lng: body.destination_lng }
  : getCoords(body.destination);

return {
  json: {
    origin_lat: origin.lat,
    origin_lng: origin.lng,
    destination_lat: destination.lat,
    destination_lng: destination.lng
  }
};

const routes = $input.first().json.routes || [];

if (!routes.length) {
  return [{
    json: {
      routes: [],
      recommended_route: null,
      explanation: "No routes were available to compare."
    }
  }];
}

// SAFETY FIRST
// Higher safety score ALWAYS wins.
// Travel time is only used when safety scores are exactly equal.

const safest = [...routes].sort((a, b) => {
  const scoreDiff = (b.safety_score ?? 0) - (a.safety_score ?? 0);

  if (scoreDiff !== 0) {
    return scoreDiff;
  }

  return (a.duration_min ?? Infinity) - (b.duration_min ?? Infinity);
})[0];

// Get the other routes for comparison
const otherRoutes = routes.filter(route => route.label !== safest.label);

const other = otherRoutes[0];

const score = safest.safety_score ?? 0;
const reports = safest.based_on_reports ?? 0;
const riskLevel = safest.risk_level ?? "unknown";
const time = safest.duration_min ?? 0;

// Collect reported issues from matched reports
const issues = [];

(safest.matched_reports || []).forEach(report => {
  if (Array.isArray(report.issues)) {
    report.issues.forEach(issue => {
      if (issue && !issues.includes(issue)) {
        issues.push(issue);
      }
    });
  }
});

// If matched reports don't contain issues, use risk level as context
let issueText = "";

if (issues.length > 0) {
  issueText = ` Nearby safety reports include concerns such as ${issues.slice(0, 4).join(", ")}.`;
} else if (riskLevel === "high") {
  issueText = " Nearby reports indicate higher-risk conditions along this route.";
} else if (riskLevel === "medium") {
  issueText = " Some safety concerns have been reported near this route.";
} else {
  issueText = " No major safety issues were identified in the available nearby reports.";
}

// Build comparison sentence
let comparisonText = "";

if (other) {
  const otherScore = other.safety_score ?? 0;
  const difference = Math.abs(score - otherScore);

  if (score > otherScore) {
    comparisonText =
      ` It has a ${difference}-point safety advantage over ${other.label}, which makes it the safer option based on the available data.`;
  } else if (score === otherScore) {
    comparisonText =
      ` Its safety score is equal to ${other.label}, so the shorter route was selected as the tie-breaker.`;
  }
}

// Travel time context
let timeText = "";

if (other) {
  const otherTime = other.duration_min ?? 0;

  if (time < otherTime) {
    timeText =
      ` It also has a shorter estimated travel time of ${time} minutes.`;
  } else if (time > otherTime) {
    timeText =
      ` Although it takes approximately ${time} minutes, travel time was not prioritized over safety.`;
  } else {
    timeText =
      ` Both routes have a similar estimated travel time, so the safety score is the deciding factor.`;
  }
}

const explanation =
  `${safest.label} is recommended because it has the highest safety score of ${score}/100. ` +
  `The score is based on ${reports} nearby safety report${reports === 1 ? "" : "s"} and the current risk level is ${riskLevel}.${issueText}` +
  `${comparisonText}${timeText} ` +
  `Safety is prioritized over travel time when selecting the recommended route.`;

return [{
  json: {
    routes,
    recommended_route: safest.label,
    explanation
  }
}];
